import{_ as a,o as n,c as i,am as r}from"./chunks/framework.Ded1aDJ9.js";const h=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),t={name:"glossaire.md"};function o(s,e,l,u,d,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="auc" tabindex="-1">AUC <a class="header-anchor" href="#auc" aria-label="Permalink to &quot;AUC&quot;">​</a></h3><p>Mesure de la capacité d&#39;un modèle à classer les cas positifs avant les négatifs, de 0,5 (hasard) à 1 (parfait). Une AUC de 1,00 sur des données réelles est presque toujours le signe d&#39;une fuite.</p><h3 id="baseline" tabindex="-1">Baseline <a class="header-anchor" href="#baseline" aria-label="Permalink to &quot;Baseline&quot;">​</a></h3><p>Le modèle le plus simple possible (par exemple « personne ne part »), qu&#39;on calcule avant tout autre : un modèle qui ne fait pas mieux ne sert à rien.</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="churn" tabindex="-1">Churn <a class="header-anchor" href="#churn" aria-label="Permalink to &quot;Churn&quot;">​</a></h3><p>Le départ d&#39;un client. Il n&#39;a pas de définition universelle : on l&#39;écrit pour chaque projet, avec son horizon (ici, aucun séjour dans les 12 mois suivants).</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="correlation-et-causalite" tabindex="-1">Corrélation et causalité <a class="header-anchor" href="#correlation-et-causalite" aria-label="Permalink to &quot;Corrélation et causalité&quot;">​</a></h3><p>Deux variables qui varient ensemble ne prouvent pas que l&#39;une cause l&#39;autre : un troisième facteur (ici, le niveau du membre) peut expliquer le lien. Une cause se prouve par un test.</p><h3 id="derive-d-un-modele" tabindex="-1">Dérive (d&#39;un modèle) <a class="header-anchor" href="#derive-d-un-modele" aria-label="Permalink to &quot;Dérive (d&#39;un modèle)&quot;">​</a></h3><p>Quand les données ou les comportements changent après l&#39;entraînement, et que le modèle se trompe sans le dire. On la surveille sur ce qu&#39;on peut mesurer tout de suite.</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="fuite-de-la-cible" tabindex="-1">Fuite (de la cible) <a class="header-anchor" href="#fuite-de-la-cible" aria-label="Permalink to &quot;Fuite (de la cible)&quot;">​</a></h3><p>Une variable qui contient une information sur la cible, connue seulement après le moment de la prédiction. Elle rend le modèle excellent au test et inutile en production. À ne pas confondre avec une fuite de données vers un outil.</p><h3 id="fuite-de-donnees" tabindex="-1">Fuite de données <a class="header-anchor" href="#fuite-de-donnees" aria-label="Permalink to &quot;Fuite de données&quot;">​</a></h3><p>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</p><h3 id="garde-fou" tabindex="-1">Garde-fou <a class="header-anchor" href="#garde-fou" aria-label="Permalink to &quot;Garde-fou&quot;">​</a></h3><p>Indicateur surveillé pour vérifier qu&#39;un progrès ne se fait pas au détriment d&#39;autre chose.</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="groupe-temoin" tabindex="-1">Groupe témoin <a class="header-anchor" href="#groupe-temoin" aria-label="Permalink to &quot;Groupe témoin&quot;">​</a></h3><p>Des personnes qui ne reçoivent pas l&#39;action (ici, pas d&#39;appel), pour mesurer l&#39;effet réel de l&#39;action par comparaison.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="kpi" tabindex="-1">KPI <a class="header-anchor" href="#kpi" aria-label="Permalink to &quot;KPI&quot;">​</a></h3><p>Indicateur de suivi d&#39;une activité (volume, délai, taux). Tous les KPI ne sont pas des résultats clés.</p><h3 id="llm-juge-llm-as-a-judge" tabindex="-1">LLM juge (LLM-as-a-judge) <a class="header-anchor" href="#llm-juge-llm-as-a-judge" aria-label="Permalink to &quot;LLM juge (LLM-as-a-judge)&quot;">​</a></h3><p>Un modèle de langage utilisé pour évaluer les réponses d&#39;un autre. Pratique pour trier, mais indulgent avec les réponses plausibles : on lui donne la source et on vérifie ses verdicts.</p><h3 id="machine-learning" tabindex="-1">Machine learning <a class="header-anchor" href="#machine-learning" aria-label="Permalink to &quot;Machine learning&quot;">​</a></h3><p>Des modèles qui apprennent une règle à partir de données étiquetées (une régression, un gradient boosting) pour prédire sur de nouveaux cas. Différent d&#39;un LLM, qui génère du texte.</p><h3 id="precision-et-rappel" tabindex="-1">Précision et rappel <a class="header-anchor" href="#precision-et-rappel" aria-label="Permalink to &quot;Précision et rappel&quot;">​</a></h3><p>Parmi les cas désignés par le modèle, la part qui est vraie (précision) ; parmi tous les vrais cas, la part que le modèle a trouvée (rappel).</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;RAG&quot;">​</a></h3><p>Retrieval-Augmented Generation : l&#39;assistant cherche des passages dans une source (ici, la FAQ) et répond à partir d&#39;eux. Il peut quand même inventer, mélanger ou citer une ancienne version.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="valeur-sentinelle" tabindex="-1">Valeur sentinelle <a class="header-anchor" href="#valeur-sentinelle" aria-label="Permalink to &quot;Valeur sentinelle&quot;">​</a></h3><p>Une valeur conventionnelle (999, -1) qui veut dire « inconnu » ou « erreur » : prise pour un vrai nombre, elle fausse les moyennes.</p>',53)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
